import {DOMAINS,BANK_VERSION,createAttempt,answerAttempt,finishAttempt,remainingMs,grade,validAttempt,formatTime} from './core.mjs';

const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const KEY='mcip-practice-v1';
let bank=[],active=null,history=[],screen='home',selected=null,reviewFilter='missed',reviewDomain='all',saveFailed=false,notice='',lastWarning='',storageBlocked=false;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>({arrow:'↗',flag:'⚑',check:'✓',clock:'◷',back:'←',next:'→',close:'×'}[name]||'');
const button=(label,action,cls='button',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const date=v=>new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const setQuestions=s=>bank.filter(q=>q.set===s);
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:BANK_VERSION,active,history}));saveFailed=false;}catch{saveFailed=true;if(!storageBlocked){storageBlocked=true;announce('Progress cannot be saved on this device. Keep this page open until you finish.');}}}
function restore(){active=null;history=[];try{const raw=localStorage.getItem(KEY);if(!raw)return;const d=JSON.parse(raw);if(d.version!==BANK_VERSION){notice='The question bank has changed. Start a fresh exam with this version.';return;}history=(Array.isArray(d.history)?d.history:[]).filter(a=>validAttempt(a,bank)&&a.status==='submitted').slice(0,50);if(validAttempt(d.active,bank)&&d.active.status==='active')active=d.active;else if(d.active)notice='An incomplete saved attempt could not be restored. Your valid results are still available.';}catch{notice='Saved progress could not be loaded. You can start a fresh attempt.';}}
function announce(message){document.querySelector('#announcer').textContent=message;}
function shell(content,tab='Practice'){return `<header class="site-header"><div class="header-inner"><a class="brand" href="#" data-action="home" aria-label="Pro CIP Prep home"><span class="brandmark">P</span><span>Pro CIP<span class="brand-sub">PREP</span></span></a><nav aria-label="Main navigation">${['Practice','Progress','Study library'].map(t=>`<button class="nav-link ${tab===t?'active':''}" data-action="${t==='Practice'?'home':t==='Progress'?'history':'library'}" ${tab===t?'aria-current="page"':''}>${t}</button>`).join('')}</nav><span class="header-note"><i></i> 2023 CIP blueprint</span></div></header>${saveFailed?'<div class="storage-warning" role="alert">Progress cannot be saved on this device. Keep this page open until you finish.</div>':''}<main id="main">${content}</main><footer><span>Pro CIP Prep · Independent practice, informed study.</span><span>Not affiliated with AIIM. Practice results do not guarantee certification.</span></footer>`;}
function render(){if(screen==='exam'){renderExam();return;}if(screen==='results'){renderResults();return;}if(screen==='history'){renderHistory();return;}if(screen==='library'){renderLibrary();return;}renderHome();}
function navigate(next){screen=next;render();window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
function renderHome(){
  const scores=history.map(a=>grade(a,bank).score),best=scores.length?Math.max(...scores):null;
  app.innerHTML=shell(`<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</p><h1 tabindex="-1">Build confidence.<br><em>Earn your CIP.</em></h1><p class="lead">Practice the decisions that matter. Five complete exams, thoughtful explanations, and a study plan built around your results.</p><div class="hero-actions">${button(active?'Resume your exam <span>→</span>':'Choose a practice exam <span>→</span>',active?'resume':'scroll-exams','button primary')}${button('Explore the study library','library','text-button')}</div><div class="hero-proof"><span>✓ 500 original questions</span><span>✓ Five knowledge domains</span><span>✓ Explanations for every answer</span></div></div><aside class="exam-preview"><div class="preview-top"><span class="eyebrow">THE PRACTICE STANDARD</span><span class="mini-icon">◷</span></div><div class="preview-number">120<span>minutes to think like<br>an information professional</span></div><div class="preview-rule"></div><div class="preview-stats"><div><b>100</b><span>questions per exam</span></div><div><b>5</b><span>complete exam sets</span></div></div><p>One best answer. A real deadline.<br>A clear path to what comes next.</p><span class="preview-decoration" aria-hidden="true">✳</span></aside></section>
  <section class="wrap metrics" aria-label="Your progress"><div><span>YOUR STUDY SNAPSHOT</span><strong>${history.length?`${history.length} attempt${history.length===1?'':'s'} completed`:'A fresh start, a focused goal'}</strong></div><div><span>Best practice score</span><strong>${best===null?'—':best+'%'} <small>${best===null?'Take your first exam':'Across saved attempts'}</small></strong></div><div><span>Exam sets explored</span><strong>${new Set(history.map(a=>a.set)).size}<small>of 5 complete sets</small></strong></div></section>
  ${notice?`<div class="wrap notice">${esc(notice)}</div>`:''}
  ${active?`<section class="wrap resume-banner"><div><b>Your exam is in progress</b><p>Set ${active.set} · ${Object.keys(active.answers).length} of 100 answered · the clock is still running.</p></div>${button('Resume exam →','resume','button primary')}</section>`:''}
  <section class="wrap section" id="exams"><div class="section-heading"><div><p class="eyebrow">PRACTICE WITH PURPOSE</p><h2>Choose your next challenge</h2></div><p>Each set follows the same blueprint.<br>Take a fresh set to measure your progress.</p></div><div class="exam-cards">${[4,5,6,7,8].map((s,i)=>{const attempts=history.filter(a=>a.set===s);return `<article class="exam-card"><div class="card-top"><span class="set-number">0${i+1}</span><span class="pill">${attempts.length?`${attempts.length} completed`:'Not attempted'}</span></div><h3>Practice Set ${s}</h3><p>${['Start with a clear baseline.','Put your judgment to work.','Turn knowledge into decisions.','Challenge your assumptions.','Bring it all together.'][i]}</p><div class="card-facts"><span>100 questions</span><span>120 minutes</span></div>${button(active?.set===s?'Resume exam →':'Start exam →',active?.set===s?'resume':'start','button card-button',`data-set="${s}"`)}</article>`}).join('')}</div><p class="muted small">Sets 4–8 continue the earlier printable series. Each contains 30 medium, 50 difficult, and 20 very difficult questions. Concepts recur across sets; scenarios are distinct.</p></section>
  <section class="wrap how-section"><div><p class="eyebrow">A BETTER REVIEW LOOP</p><h2>Practice. Understand.<br>Come back stronger.</h2></div><div class="how-steps"><article><span>01</span><div><h3>Take a realistic exam</h3><p>Work closed book. Flag uncertain answers and revisit them before the timer ends.</p></div></article><article><span>02</span><div><h3>Understand every decision</h3><p>See your answer, the best answer, and the reasoning that separates them.</p></div></article><article><span>03</span><div><h3>Focus your next study session</h3><p>Follow your domain priorities and precise references in your CIP study guide.</p></div></article></div></section>
  <section class="wrap note-panel"><b>Know which exam you are preparing for.</b><p>This bank follows AIIM’s 2023 CIP blueprint, checked October 15, 2026. AIIM has announced a new exam becoming standard in April 2027. Check the official blueprint before using these sets for that version.</p><a href="https://www.aiim.org/education-section/cip" target="_blank" rel="noopener">Check AIIM’s current exam details ↗</a></section>`);
}
function startDialog(set){if(active){modal.innerHTML=`<h2 id="modal-title">You have an exam in progress</h2><p>Finish your current attempt before starting another set. Its two-hour clock is still running.</p><div class="dialog-actions">${button('Close','close-modal','button secondary')}${button('Resume current exam','resume','button primary')}</div>`;}else{modal.innerHTML=`<p class="eyebrow">PRACTICE SET ${set}</p><h2 id="modal-title">Ready for your two-hour session?</h2><p>Choose one best answer for each of the 100 questions. Work closed book and use the question map to revisit flagged or unanswered items.</p><ul class="check-list"><li>The timer starts when you begin. It keeps running if you leave or refresh.</li><li>Your answers are saved on this device when browser storage is available.</li><li>The exam submits automatically at the deadline. Answers and explanations appear after submission.</li></ul><p class="small muted">This is independent practice, not a proctored certification exam. Published CIP pass threshold: 60%. Higher practice targets are guidance, not a prediction.</p><div class="dialog-actions">${button('Not yet','close-modal','button secondary')}${button('Begin timed exam','begin','button primary',`data-set="${set}"`)}</div>`;}modal.showModal();}
function renderExam(){if(!active){navigate('home');return;}if(!remainingMs(active)){submit(true);return;}const qs=setQuestions(active.set),q=qs[active.index],count=Object.keys(active.answers).length,flagged=active.flags.includes(q.id);
  app.innerHTML=`<header class="exam-header"><a href="#" class="brand" data-action="home"><span class="brandmark">P</span><span>Practice Set ${active.set}<span class="brand-sub">TIMED EXAM</span></span></a><div class="exam-header-right"><div class="timer" role="timer" aria-label="Time remaining"><span>TIME REMAINING</span><b id="time-left">${formatTime(remainingMs(active))}</b></div>${button('Finish exam','finish','button primary')}</div></header>${saveFailed?'<div class="storage-warning" role="alert">Saving is unavailable. Keep this page open to preserve your answers.</div>':''}<main id="main" class="exam-layout"><section class="question-panel"><div class="question-meta"><span>QUESTION ${active.index+1} <span class="muted">OF 100</span></span>${button(`${flagged?'⚑ Flagged':'⚑ Flag for review'}`,'flag',`flag-button ${flagged?'flagged':''}`,`aria-pressed="${flagged}"`)}</div><div class="thin-progress"><span style="width:${active.index+1}%"></span></div><h1 tabindex="-1" class="question-stem">${esc(q.stem)}</h1><fieldset class="choices"><legend class="sr-only">Choose the best answer</legend>${q.choices.map((o,i)=>`<label class="choice ${active.answers[q.id]===i?'selected':''}"><input type="radio" name="answer" value="${i}" ${active.answers[q.id]===i?'checked':''}><span class="choice-letter">${'ABCD'[i]}</span><span>${esc(o)}</span><span class="choice-check" aria-hidden="true">${active.answers[q.id]===i?'✓':''}</span></label>`).join('')}</fieldset><div class="question-bottom"><span id="save-status" class="muted small">${saveFailed?'Keep this page open':'Progress saved on this device'}</span>${button('Clear answer','clear','text-button',active.answers[q.id]===undefined?'disabled':'')}</div><div class="question-nav">${button('← Previous','prev','button secondary',active.index===0?'disabled':'')}<span class="muted small">Take a breath. Choose the best answer.</span>${button(active.index===99?'Review & finish':'Next question →',active.index===99?'finish':'next','button primary')}</div></section><aside class="question-map"><div class="map-heading"><h2>Your progress</h2><b id="answered-count">${count}<small> / 100</small></b></div><div class="progress-track"><span id="answer-progress" style="width:${count}%"></span></div><p class="small muted">Select a number to jump to a question.</p><div class="map-grid">${qs.map((x,i)=>`<button data-action="jump" data-index="${i}" class="map-number ${active.answers[x.id]!==undefined?'answered':''} ${active.flags.includes(x.id)?'flagged':''} ${active.index===i?'current':''}" aria-label="Question ${i+1}, ${active.answers[x.id]!==undefined?'answered':'unanswered'}${active.flags.includes(x.id)?', flagged':''}" ${active.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><div class="map-legend"><span><i class="answered"></i>Answered</span><span><i></i>Unanswered</span><span><i class="flagged"></i>Flagged</span></div><div class="exam-tip"><b>Make time for a final pass.</b><p>Flag a question if you’re unsure. You can change any answer before submitting.</p></div>${button('Back to practice dashboard','home','text-button')}<p class="small muted">Leaving this screen does not pause the clock.</p></aside></main>`;
}
function submit(auto=false){if(!active)return;const result=finishAttempt(active,auto?Math.max(Date.now(),active.deadline):Date.now());history=[result,...history.filter(x=>x.id!==result.id)].slice(0,50);active=null;selected=result;save();if(modal.open)modal.close();reviewFilter='missed';reviewDomain='all';navigate('results');announce(auto?'Time is up. Your exam has been submitted.':'Exam submitted. Your results are ready.');}
function finishDialog(){if(!active)return;const answered=Object.keys(active.answers).length;modal.innerHTML=`<h2 id="modal-title">Submit your exam?</h2><p>You answered <strong>${answered} of 100</strong> questions and flagged <strong>${active.flags.length}</strong> for review.</p>${answered<100?`<p class="notice">${100-answered} unanswered question${answered===99?'':'s'} will receive zero points.</p>`:'<p>All questions have an answer. You can review them once more before submitting.</p>'}<p>Submission ends this attempt. You’ll then see your score, explanations, and study priorities.</p><div class="dialog-actions">${button('Keep reviewing','close-modal','button secondary')}${button('Submit and see results','submit','button primary')}</div>`;modal.showModal();}
function sourceText(q){const domain=q.source.file.match(/Domain-(\d)/)?.[1]||q.domain;return `CIP Study Guide 2023 · Domain ${domain} PDF · page${q.source.pages.length>1?'s':''} ${q.source.pages.join(', ')}`;}
function sourceLink(q){return `<p class="source-ref"><span>STUDY REFERENCE</span>${esc(sourceText(q))}${q.source.supplement_url?`<br><a href="${esc(q.source.supplement_url)}" target="_blank" rel="noopener">NIST digital signature standard ↗</a>`:''}</p>`;}
function reviewCard(o,a){const status=o.correct?'Correct':o.selected===null?'Unanswered':'Incorrect';return `<article class="review-card"><div class="review-top"><span class="result-tag ${o.correct?'correct':'incorrect'}">${o.correct?'✓':'•'} ${status}</span><span>Question ${o.q.number} · Domain ${o.q.domain} · ${esc(o.q.difficulty)}${a.flags.includes(o.q.id)?' · Flagged':''}</span></div><h3>${esc(o.q.stem)}</h3><ol class="review-choices">${o.q.choices.map((choice,i)=>`<li class="${i===o.q.correctIndex?'right':i===o.selected?'wrong':''}"><span class="choice-letter">${'ABCD'[i]}</span><span>${esc(choice)}</span>${i===o.q.correctIndex?'<b>Best answer ✓</b>':i===o.selected?'<b>Your answer</b>':''}</li>`).join('')}</ol>${o.selected===null?'<p class="unanswered-note">You did not select an answer. This question received zero points.</p>':''}<div class="explanation"><h4>${o.correct?'Why this is the best answer':o.selected===null?'What to look for next time':'Why your answer falls short'}</h4><p>${esc(o.q.rationale)}</p><p class="objective">Objective ${esc(o.q.objective)} · ${esc(o.q.topic)}</p>${sourceLink(o.q)}</div></article>`;}
function planCards(result){return result.priorities.map((d,i)=>{const missed=result.outcomes.filter(o=>o.q.domain===d.id&&!o.correct);const topics=new Map();for(const o of missed){const key=o.q.objective;if(!topics.has(key))topics.set(key,{objective:key,topic:o.q.topic,questions:[],count:0});const t=topics.get(key);t.count++;t.questions.push(o.q);}const focus=[...topics.values()].sort((a,b)=>b.count-a.count).slice(0,3);return `<article class="priority-card"><div class="priority-rank">${String(i+1).padStart(2,'0')}</div><div><p class="eyebrow">${d.lost?'STUDY PRIORITY':'MAINTAIN YOUR STRENGTH'}</p><h3>${esc(d.short)}</h3><p>${d.correct} of ${d.total} correct · ${d.percent}% · ${d.lost} point${d.lost===1?'':'s'} missed</p>${focus.length?`<ul class="focus-topics">${focus.map(t=>`<li><b>Objective ${esc(t.objective)}: ${esc(t.topic)}</b><span>${esc(sourceText(t.questions[0]))}</span></li>`).join('')}</ul>`:'<p class="muted">All questions in this domain were correct. Revisit flagged answers and test this strength on a fresh set.</p>'}<p class="small">${d.lost?'Read the referenced pages, explain the rule in your own words, then revisit the missed scenarios. Use a fresh set to check improvement.':'Keep this domain in your revision rotation.'}</p></div></article>`;}).join('');}
function renderResults(){const a=selected;if(!a){navigate('history');return;}const r=grade(a,bank),elapsed=Math.max(0,a.submittedAt-a.startedAt);let rows=r.outcomes.filter(o=>(reviewDomain==='all'||o.q.domain===Number(reviewDomain))&&(reviewFilter==='all'||reviewFilter==='missed'&&!o.correct||reviewFilter==='flagged'&&a.flags.includes(o.q.id)||reviewFilter==='correct'&&o.correct));
  app.innerHTML=shell(`<section class="wrap results-title"><div><p class="eyebrow">PRACTICE SET ${a.set} · ${esc(date(a.submittedAt))}</p><h1 tabindex="-1">A clear picture.<br><em>A focused next step.</em></h1><p>${a.reason==='time'?'Time expired and your saved answers were submitted automatically.':'Your exam is complete. Now turn each decision into a learning opportunity.'}</p></div>${button('Print study report','print','button secondary')}</section><section class="wrap result-summary"><div class="score-ring" style="--score:${r.score}%"><div><strong>${r.score}<small>%</small></strong><span>${r.correct} / ${r.total} correct</span></div></div><div class="result-summary-copy"><span class="pill ${r.score>=60?'success':'amber'}">${r.score>=60?'Published pass threshold met':'Below published pass threshold'}</span><h2>${r.band}</h2><p>${r.score>=80?'Keep your momentum and check your weaker domains before your next fresh exam.':r.score>=60?'You reached 60%. Use the review below to close gaps and build a stronger margin.':'Use your study priorities to rebuild the concepts that cost the most points.'}</p><div class="result-stats"><span><b>${r.answered}</b> answered</span><span><b>${100-r.answered}</b> unanswered</span><span><b>${Math.floor(elapsed/60000)}m ${Math.floor(elapsed%60000/1000)}s</b> used</span></div><p class="small muted">Practice target: 80% overall and 75% in every domain. These are study goals, not validated readiness predictions. This is not a ranking against other students.</p></div></section>
  <section class="wrap section"><div class="section-heading"><div><p class="eyebrow">SEE THE WHOLE PICTURE</p><h2>Your domain breakdown</h2></div><span class="small muted">Suggested domain target: 75%</span></div><div class="domain-results">${r.domains.map(d=>`<article><div class="domain-result-top"><span>0${d.id} · ${esc(d.short)}</span><b>${d.percent}%</b></div><div class="domain-bar"><span class="${d.percent>=75?'strong':''}" style="width:${d.percent}%"></span><i title="75% study target"></i></div><div class="small muted">${d.correct} / ${d.total} correct · ${d.weight}% of the exam</div></article>`).join('')}</div></section>
  <section class="wrap section" id="study-plan"><div class="section-heading"><div><p class="eyebrow">MAKE YOUR NEXT HOUR COUNT</p><h2>Your study priorities</h2></div><p>Ranked by points missed in this attempt.<br>Open your licensed CIP study guide at the pages below.</p></div><div class="priorities">${planCards(r)}</div><p class="small muted">References use page numbers within the separate domain PDFs, not a combined guide. Some objectives draw on another domain’s material. This plan reflects one practice attempt.</p><a class="text-link" href="https://www.aiim.org/education-section/cip" target="_blank" rel="noopener">Find official CIP preparation materials through AIIM ↗</a></section>
  <section class="wrap section" id="answer-review"><div class="section-heading"><div><p class="eyebrow">LEARN FROM THE DETAILS</p><h2>Review your answers</h2></div><p>${rows.length} question${rows.length===1?'':'s'} shown</p></div><div class="review-controls"><div class="filter-buttons" role="group" aria-label="Review filter">${[['missed','Missed'],['all','All answers'],['flagged','Flagged'],['correct','Correct']].map(([v,l])=>button(l,'filter',`filter-button ${reviewFilter===v?'active':''}`,`data-filter="${v}" aria-pressed="${reviewFilter===v}"`)).join('')}</div><label>Domain <select id="domain-filter"><option value="all">All domains</option>${DOMAINS.map(d=>`<option value="${d.id}" ${String(d.id)===reviewDomain?'selected':''}>${d.id}. ${esc(d.short)}</option>`).join('')}</select></label></div><div class="review-list">${rows.length?rows.map(o=>reviewCard(o,a)).join(''):'<div class="empty-state"><b>No questions in this view.</b><p>Choose another filter to explore the rest of your answers.</p></div>'}</div></section><div class="wrap bottom-actions">${button('Choose your next exam →','home','button primary')}${button('View attempt history','history','button secondary')}</div>`,'Progress');
}
function renderHistory(){app.innerHTML=shell(`<section class="wrap page-title"><p class="eyebrow">YOUR LEARNING JOURNEY</p><h1 tabindex="-1">Progress, one attempt at a time.</h1><p>Results are saved on this device. Up to 50 completed attempts are retained. A repeated set can reflect memory as well as learning.</p></section><section class="wrap history-section">${history.length?`<div class="history-list">${history.map(a=>{const r=grade(a,bank);return `<article class="history-card"><div><span class="eyebrow">${esc(date(a.submittedAt))}</span><h2>Practice Set ${a.set}</h2><p>${esc(r.band)}</p></div><div class="history-score">${r.score}<small>%</small></div>${button('Review results →','review','button secondary',`data-id="${esc(a.id)}"`)}</article>`;}).join('')}</div>`:`<div class="empty-state"><span class="large-symbol">↗</span><h2>Your first result starts the story.</h2><p>Complete a timed exam to see your scores and study priorities here.</p>${button('Choose a practice exam','home','button primary')}</div>`}</section>`,'Progress');}
function renderLibrary(){app.innerHTML=shell(`<section class="wrap page-title"><p class="eyebrow">BUILD KNOWLEDGE THAT STAYS</p><h1 tabindex="-1">Your CIP study compass.</h1><p>Use official materials as your foundation. Use practice results to decide where to spend your next study session.</p></section><section class="wrap library-grid">${DOMAINS.map(d=>`<article class="library-card"><span class="eyebrow">DOMAIN 0${d.id} · ${d.weight}% OF THE EXAM</span><h2>${esc(d.name)}</h2><p>${['Review capture requirements, collaboration, information access, and long-term preservation.','Review metadata, classification, analytics, search, and the value of usable information.','Review process analysis, workflow, case management, automation, and performance measures.','Review lifecycle controls, records management, privacy, security, retention, and governance.','Review strategy, business cases, requirements, implementation, adoption, and benefits.'][d.id-1]}</p><div class="library-source"><b>Start with your domain study guide</b><span>CIP Study Guide 2023 · Domain ${d.id} PDF</span></div><a href="https://www.aiim.org/education-section/cip" target="_blank" rel="noopener">Official AIIM preparation resources ↗</a></article>`).join('')}<article class="library-card dark"><span class="eyebrow">STUDY WITH A PLAN</span><h2>Close the loop on each mistake.</h2><ol><li>Read the explanation without rushing.</li><li>Open the cited pages in your licensed guide.</li><li>Write down the rule and the clue you missed.</li><li>Apply it again on a fresh practice set.</li></ol></article></section><section class="wrap note-panel"><h2>Sources and exam version</h2><p>The five sets follow the AIIM CIP 2023 blueprint: 100 multiple-choice questions in 120 minutes, with a published passing threshold of 60%. AIIM announces a revised exam becoming standard in April 2027; check the version that applies to your exam date.</p><div class="resource-links"><a href="https://www.aiim.org/education-section/cip" target="_blank" rel="noopener">AIIM CIP exam and preparation ↗</a><a href="https://332414.fs1.hubspotusercontent-na1.net/hubfs/332414/CIP/CIP%20v2023%20Exam%20Blueprint-FINAL.pdf" target="_blank" rel="noopener">2023 examination blueprint ↗</a></div><p class="small muted">Study guides are not redistributed here. Page references identify the relevant sections in the separately supplied domain PDFs. The question bank is independent practice material.</p></section>`,'Study library');}
function goQuestion(index){if(!active)return;active.index=Math.max(0,Math.min(99,index));save();renderExam();window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const action=el.dataset.action;
  if(action==='close-modal'){modal.close();return;}
  if(action==='start'){startDialog(Number(el.dataset.set));return;}
  if(action==='begin'){if(active)return;active=createAttempt(Number(el.dataset.set));save();modal.close();navigate('exam');return;}
  if(action==='resume'){if(modal.open)modal.close();navigate('exam');return;}
  if(action==='home'||action==='history'||action==='library'){navigate(action);return;}
  if(action==='scroll-exams'){document.querySelector('#exams')?.scrollIntoView({behavior:'smooth'});return;}
  if(action==='jump'){goQuestion(Number(el.dataset.index));return;}
  if(action==='next'||action==='prev'){goQuestion(active.index+(action==='next'?1:-1));return;}
  if(action==='flag'){const q=setQuestions(active.set)[active.index];active.flags=active.flags.includes(q.id)?active.flags.filter(x=>x!==q.id):[...active.flags,q.id];save();renderExam();document.querySelector('[data-action="flag"]')?.focus();return;}
  if(action==='clear'){const q=setQuestions(active.set)[active.index];if(!answerAttempt(active,q.id,null)){submit(true);return;}save();renderExam();return;}
  if(action==='finish'){finishDialog();return;}
  if(action==='submit'){submit();return;}
  if(action==='review'){selected=history.find(a=>a.id===el.dataset.id);reviewFilter='missed';reviewDomain='all';navigate('results');return;}
  if(action==='filter'){reviewFilter=el.dataset.filter;renderResults();document.querySelector('#answer-review')?.scrollIntoView();document.querySelector(`[data-filter="${reviewFilter}"]`)?.focus({preventScroll:true});return;}
  if(action==='print'){window.print();}
});
document.addEventListener('change',event=>{
  if(event.target.matches('input[name="answer"]')&&active){const choice=Number(event.target.value),q=setQuestions(active.set)[active.index];if(!answerAttempt(active,q.id,choice)){submit(true);return;}save();renderExam();document.querySelector(`input[name="answer"][value="${choice}"]`)?.focus({preventScroll:true});}
  if(event.target.id==='domain-filter'){reviewDomain=event.target.value;renderResults();document.querySelector('#answer-review')?.scrollIntoView();document.querySelector('#domain-filter')?.focus({preventScroll:true});}
});
function tick(){if(!active)return;const ms=remainingMs(active);if(!ms){submit(true);return;}const el=document.querySelector('#time-left');if(el){el.textContent=formatTime(ms);el.closest('.timer').classList.toggle('urgent',ms<=5*60*1000);}const mark=ms<=5*60*1000?'5':ms<=15*60*1000?'15':'';if(mark&&mark!==lastWarning){lastWarning=mark;announce(`${mark} minutes or less remain in your exam.`);}}
document.addEventListener('visibilitychange',tick);
// Read the latest save before changing tabs so two windows do not silently overwrite an attempt.
window.addEventListener('storage',event=>{if(event.key===KEY){restore();if(screen==='exam'&&!active){notice='This attempt was updated in another tab. Open its result in Progress.';screen='history';}render();tick();}});
try{const response=await fetch('./data/questions.json');if(!response.ok)throw new Error('Question bank unavailable');bank=await response.json();if(bank.length!==500)throw new Error('Question bank incomplete');restore();if(active&&!remainingMs(active))submit(true);else render();setInterval(tick,1000);}catch{app.innerHTML='<main class="loading"><span class="brandmark">P</span><h1>The exam bank could not load.</h1><p>Check your connection, then reload this page. Your previously saved progress has not been removed.</p><button class="button primary" onclick="location.reload()">Try again</button></main>';}
